-- Conflict resolution: If an effect is enabled, disable any effect in the same category with the same propertyGroup
local function toggleEffect(categoryKey: string, effectId: string, isEnabled: boolean)
    for _, cat in CATALOG do
        if cat.key == categoryKey then
            local targetEffect: EffectDef? = nil
            for _, eff in cat.effects do
                if eff.id == effectId then
                    targetEffect = eff
                    eff.enabled = isEnabled
                end
            end
            if isEnabled and targetEffect then
                -- Disable other effects in the same propertyGroup
                for _, eff in cat.effects do
                    if eff.id ~= effectId and eff.propertyGroup == targetEffect.propertyGroup then
                        eff.enabled = false
                    end
                end
            end
        end
    end
end


-- ===== SelectionHelper.lua =====
-- ================================================================
--  Button FX Studio | Selection Helper
--  Made by KAMIRIM
--  Finds valid target buttons from the current Studio selection.
-- ================================================================

local Selection = game:GetService("Selection")
local History   = game:GetService("ChangeHistoryService")

-- Returns all selected TextButton / ImageButton / Frame instances (including recursive search in containers)
local function getButtons(): { Instance }
    local out = {}
    local seen = {}

    local function addCandidate(obj: Instance)
        if not seen[obj] then
            seen[obj] = true
            table.insert(out, obj)
        end
    end

    for _, obj in Selection:Get() do
        if obj:IsA("TextButton") or obj:IsA("ImageButton") then
            addCandidate(obj)
        elseif obj:IsA("Frame") or obj:IsA("CanvasGroup") or obj:IsA("ScreenGui") or obj:IsA("Folder") then
            local foundInside = 0
            for _, desc in obj:GetDescendants() do
                if desc:IsA("TextButton") or desc:IsA("ImageButton") then
                    addCandidate(desc)
                    foundInside += 1
                end
            end
            if foundInside == 0 and (obj:IsA("Frame") or obj:IsA("CanvasGroup")) then
                addCandidate(obj)
            end
        end
    end
    return out
end


