local FX_SCRIPT_NAME = "ButtonFX"

local function getActiveEffectsList(categoryKey: string): { EffectDef }
    local list = {}
    for _, cat in CATALOG do
        if cat.key == categoryKey then
            for _, eff in cat.effects do
                if eff.enabled then
                    table.insert(list, eff)
                end
            end
        end
    end
    return list
end

