    end
    return removed
end


-- ===== Builder.lua =====
-- ================================================================
--  Button FX Studio | UI Builder Helpers
--  Made by KAMIRIM
--  Short helper functions to create Roblox UI instances cleanly.
-- ================================================================

-- Creates a plain Frame
local function newFrame(
    parent : Instance,
    name   : string,
    size   : UDim2,
    pos    : UDim2,
    color  : Color3?
): Frame
    local f = Instance.new("Frame")
    f.Name, f.Size, f.Position = name, size, pos
    if color then
        f.BackgroundColor3 = color
    else
        f.BackgroundTransparency = 1
    end
    f.BorderSizePixel  = 0
    f.Parent           = parent
    return f
end

-- Creates a TextLabel
local function newLabel(
    parent   : Instance,
    text     : string,
    size     : UDim2,
    pos      : UDim2,
    color    : Color3,
    fontSize : number,
    bold     : boolean
): TextLabel
    local l = Instance.new("TextLabel")
    l.Size, l.Position  = size, pos
    l.BackgroundTransparency = 1
    l.BorderSizePixel   = 0
    l.Text              = text
    l.TextColor3        = color
    l.TextSize          = fontSize
    l.Font              = if bold then Enum.Font.GothamBold else Enum.Font.Gotham
    l.TextXAlignment    = Enum.TextXAlignment.Left
    l.TextYAlignment    = Enum.TextYAlignment.Center
    l.TextTruncate      = Enum.TextTruncate.AtEnd
    l.Parent            = parent
    return l
end

-- Creates a TextButton
local function newBtn(
    parent    : Instance,
    name      : string,
    size      : UDim2,
    pos       : UDim2,
    bg        : Color3,
    text      : string,
    textColor : Color3,
    fontSize  : number
): TextButton
    local b = Instance.new("TextButton")
    b.Name, b.Size, b.Position = name, size, pos
    b.BackgroundColor3 = bg
    b.BorderSizePixel  = 0
    b.Text             = text
    b.TextColor3       = textColor
    b.TextSize         = fontSize
    b.Font             = Enum.Font.Gotham
    b.AutoButtonColor  = false
    b.Parent           = parent
    return b
end

-- Adds a UIStroke border to any GuiObject
local function addStroke(target: GuiObject, color: Color3, thickness: number)
    local s = Instance.new("UIStroke")
    s.Color            = color
    s.Thickness        = thickness
    s.ApplyStrokeMode  = Enum.ApplyStrokeMode.Border
    s.Parent           = target
    return s
end

-- Adds left padding to a GuiObject
local function addPadLeft(target: GuiObject, px: number)
    local p = Instance.new("UIPadding")
    p.PaddingLeft = UDim.new(0, px)
    p.Parent      = target
end

-- Adds a UIListLayout (vertical) with LayoutOrder sorting
local function addVList(parent: Instance, gap: number): UIListLayout
    local l = Instance.new("UIListLayout")
    l.FillDirection = Enum.FillDirection.Vertical
    l.SortOrder     = Enum.SortOrder.LayoutOrder
    l.Padding       = UDim.new(0, gap)
    l.Parent        = parent
    return l
end

-- Adds UIPadding to a frame
local function addPadding(parent: Instance, top: number, right: number, bottom: number, left: number)
    local p = Instance.new("UIPadding")
    p.PaddingTop    = UDim.new(0, top)
    p.PaddingRight  = UDim.new(0, right)
    p.PaddingBottom = UDim.new(0, bottom)
    p.PaddingLeft   = UDim.new(0, left)
    p.Parent        = parent
end


