local function createNumberInput(
    parent: Instance,
    label: string,
    value: number,
    minVal: number,
    maxVal: number,
    onChange: (number) -> (),
    getGuideColor: (Enum.StudioStyleGuideColor, Enum.StudioStyleGuideModifier?) -> Color3
): Frame
    local row = newFrame(parent, "NumRow_" .. label,
        UDim2.new(1, 0, 0, 26),
        UDim2.new(0, 0, 0, 0),
        nil
    )

    newLabel(row, label,
        UDim2.new(0.55, 0, 1, 0),
        UDim2.new(0, 4, 0, 0),
        getGuideColor(Enum.StudioStyleGuideColor.SubText),
        11, false
    )

    local isFloat = (maxVal - minVal <= 5) or (value % 1 ~= 0) or (label:find("Speed") ~= nil) or (label:find("Interval") ~= nil) or (label:find("Scale") ~= nil) or (label:find("Duration") ~= nil) or (label:find("Amount") ~= nil)
    local step = if isFloat then 0.05 else 1

    local function roundVal(n: number): number
        if isFloat then
            return math.floor(n * 100 + 0.5) / 100
        else
            return math.floor(n + 0.5)
        end
    end

    local function formatNum(n: number): string
        if isFloat then
            return string.format("%.2f", n)
        else
            return tostring(math.floor(n + 0.5))
        end
    end

    local currentVal = roundVal(value)

    local inputContainer = newFrame(row, "InputContainer",
        UDim2.new(0.42, 0, 0, 22),
        UDim2.new(0.55, 0, 0.5, -11),
        getGuideColor(Enum.StudioStyleGuideColor.MainBackground)
    )
    addStroke(inputContainer, getGuideColor(Enum.StudioStyleGuideColor.Border), 1)

    local box = Instance.new("TextBox")
    box.Name = "ValueBox"
    box.Size = UDim2.new(1, -16, 1, 0)
    box.Position = UDim2.new(0, 4, 0, 0)
    box.BackgroundTransparency = 1
    box.TextColor3 = getGuideColor(Enum.StudioStyleGuideColor.MainText)
    box.TextSize = 11
    box.Font = Enum.Font.Gotham
    box.Text = formatNum(currentVal)
    box.BorderSizePixel = 0
    box.ClearTextOnFocus = false
    box.TextXAlignment = Enum.TextXAlignment.Left
    box.Parent = inputContainer

    local function setValue(newVal: number)
        local clamped = math.clamp(roundVal(newVal), minVal, maxVal)
        currentVal = clamped
        box.Text = formatNum(clamped)
        onChange(clamped)
    end

    box.FocusLost:Connect(function()
        local raw = box.Text:gsub("[^0-9%.%-]", "")
        local n = tonumber(raw)
        if n then
            setValue(n)
        else
            box.Text = formatNum(currentVal)
        end
    end)

    local stepper = newFrame(inputContainer, "Stepper",
        UDim2.new(0, 14, 1, 0),
        UDim2.new(1, -14, 0, 0),
        nil
    )

    local upBtn = Instance.new("TextButton")
    upBtn.Name = "UpBtn"
    upBtn.Size = UDim2.new(1, 0, 0.5, 0)
    upBtn.Position = UDim2.new(0, 0, 0, 0)
    upBtn.BackgroundColor3 = getGuideColor(Enum.StudioStyleGuideColor.Button)
    upBtn.TextColor3 = getGuideColor(Enum.StudioStyleGuideColor.ButtonText)
    upBtn.Text = "▲"
    upBtn.TextSize = 7
    upBtn.Font = Enum.Font.GothamBold
    upBtn.BorderSizePixel = 0
    upBtn.AutoButtonColor = true
    upBtn.Parent = stepper

    local downBtn = Instance.new("TextButton")
    downBtn.Name = "DownBtn"
    downBtn.Size = UDim2.new(1, 0, 0.5, 0)
    downBtn.Position = UDim2.new(0, 0, 0.5, 0)
    downBtn.BackgroundColor3 = getGuideColor(Enum.StudioStyleGuideColor.Button)
    downBtn.TextColor3 = getGuideColor(Enum.StudioStyleGuideColor.ButtonText)
    downBtn.Text = "▼"
    downBtn.TextSize = 7
    downBtn.Font = Enum.Font.GothamBold
    downBtn.BorderSizePixel = 0
    downBtn.AutoButtonColor = true
    downBtn.Parent = stepper

    upBtn.MouseButton1Click:Connect(function()
        setValue(currentVal + step)
    end)
    downBtn.MouseButton1Click:Connect(function()
        setValue(currentVal - step)
    end)

    return row
end

local function createChoiceInput(
    parent: Instance,
    label: string,
    choices: { string },
    current: string,
    onSelect: (string) -> (),
    getGuideColor: (Enum.StudioStyleGuideColor, Enum.StudioStyleGuideModifier?) -> Color3
): Frame
    local row = newFrame(parent, "ChoiceRow_" .. label,
        UDim2.new(1, 0, 0, 28),
        UDim2.new(0, 0, 0, 0),
        nil
    )

    newLabel(row, label,
        UDim2.new(0.35, 0, 1, 0),
        UDim2.new(0, 4, 0, 0),
        getGuideColor(Enum.StudioStyleGuideColor.SubText),
        11, false
    )

    local container = newFrame(row, "Pills",
        UDim2.new(0.62, 0, 1, 0),
        UDim2.new(0.36, 0, 0, 0),
        nil
    )
    local list = Instance.new("UIListLayout")
    list.FillDirection = Enum.FillDirection.Horizontal
    list.Padding = UDim.new(0, 4)
    list.Parent = container

    local btns: { [string]: TextButton } = {}

    for _, c in choices do
        local btn = newBtn(container, c,
            UDim2.new(0, 34, 0, 22),
            UDim2.new(0, 0, 0.5, -11),
            if c == current then getGuideColor(Enum.StudioStyleGuideColor.Item, Enum.StudioStyleGuideModifier.Selected)
            else getGuideColor(Enum.StudioStyleGuideColor.Button),
            c,
            if c == current then Color3.fromRGB(255, 255, 255)
            else getGuideColor(Enum.StudioStyleGuideColor.ButtonText),
            10
        )
        addStroke(btn, getGuideColor(Enum.StudioStyleGuideColor.Border), 1)
        btns[c] = btn

        btn.MouseButton1Click:Connect(function()
            onSelect(c)
            for name, b in btns do
                if name == c then
                    b.BackgroundColor3 = getGuideColor(Enum.StudioStyleGuideColor.Item, Enum.StudioStyleGuideModifier.Selected)
                    b.TextColor3 = Color3.fromRGB(255, 255, 255)
                else
                    b.BackgroundColor3 = getGuideColor(Enum.StudioStyleGuideColor.Button)
                    b.TextColor3 = getGuideColor(Enum.StudioStyleGuideColor.ButtonText)
                end
            end
        end)
    end

    return row
end

local function colorToHex(c: Color3): string
    local r = math.clamp(math.floor(c.R * 255 + 0.5), 0, 255)
    local g = math.clamp(math.floor(c.G * 255 + 0.5), 0, 255)
    local b = math.clamp(math.floor(c.B * 255 + 0.5), 0, 255)
    return string.format("#%02X%02X%02X", r, g, b)
end

local function parseHex(text: string): Color3?
    local clean = text:gsub("[^0-9A-Fa-f]", "")
    if #clean == 6 then
        local success, result = pcall(function()
            return Color3.fromHex(clean)
        end)
        if success and typeof(result) == "Color3" then
            return result
        end
    end
    return nil
end

local function createColorInput(
    parent: Instance,
    label: string,
    current: Color3,
    onSelect: (Color3) -> (),
    getGuideColor: (Enum.StudioStyleGuideColor, Enum.StudioStyleGuideModifier?) -> Color3
): Frame
    local container = newFrame(parent, "ColorGroup_" .. label,
        UDim2.new(1, 0, 0, 0),
        UDim2.new(0, 0, 0, 0),
        nil
    )
    container.AutomaticSize = Enum.AutomaticSize.Y
    addVList(container, 4)

    -- Row 1: Swatches
    local swatchRow = newFrame(container, "SwatchRow",
        UDim2.new(1, 0, 0, 26),
        UDim2.new(0, 0, 0, 0),
        nil
    )
    newLabel(swatchRow, label,
        UDim2.new(0.35, 0, 1, 0),
        UDim2.new(0, 4, 0, 0),
        getGuideColor(Enum.StudioStyleGuideColor.SubText),
        11, false
    )

    local swatchContainer = newFrame(swatchRow, "Swatches",
        UDim2.new(0.62, 0, 1, 0),
        UDim2.new(0.36, 0, 0, 0),
        nil
    )
    local list = Instance.new("UIListLayout")
    list.FillDirection = Enum.FillDirection.Horizontal
    list.Padding = UDim.new(0, 6)
    list.Parent = swatchContainer

    -- Row 2: Hex Code Input Box
    local hexRow = newFrame(container, "HexRow",
        UDim2.new(1, 0, 0, 26),
        UDim2.new(0, 0, 0, 0),
        nil
    )
    newLabel(hexRow, "Hex Code",
        UDim2.new(0.55, 0, 1, 0),
        UDim2.new(0, 4, 0, 0),
        getGuideColor(Enum.StudioStyleGuideColor.SubText),
        11, false
    )

    local hexBox = Instance.new("TextBox")
    hexBox.Name = "HexBox"
    hexBox.Size = UDim2.new(0.42, 0, 0, 22)
    hexBox.Position = UDim2.new(0.55, 0, 0.5, -11)
    hexBox.BackgroundColor3 = getGuideColor(Enum.StudioStyleGuideColor.MainBackground)
    hexBox.TextColor3 = getGuideColor(Enum.StudioStyleGuideColor.MainText)
    hexBox.TextSize = 11
    hexBox.Font = Enum.Font.Gotham
    hexBox.Text = colorToHex(current)
    hexBox.BorderSizePixel = 0
    hexBox.ClearTextOnFocus = false
    hexBox.Parent = hexRow
    addStroke(hexBox, getGuideColor(Enum.StudioStyleGuideColor.Border), 1)

    local presetColors = {
        { name = "Gold",   color = Color3.fromRGB(255, 215, 0) },
        { name = "Cyan",   color = Color3.fromRGB(0, 220, 255) },
        { name = "White",  color = Color3.fromRGB(255, 255, 255) },
        { name = "Purple", color = Color3.fromRGB(190, 80, 255) },
        { name = "Green",  color = Color3.fromRGB(50, 255, 120) },
    }

    local swatchElements: { { btn: TextButton, stroke: UIStroke, color: Color3 } } = {}
    local activeColor = current

    local function updateVisual(selectedColor: Color3)
        activeColor = selectedColor
        hexBox.Text = colorToHex(selectedColor)
        for _, s in swatchElements do
            local match = (math.abs(s.color.R - selectedColor.R) < 0.03
                       and math.abs(s.color.G - selectedColor.G) < 0.03
                       and math.abs(s.color.B - selectedColor.B) < 0.03)
            if match then
                s.stroke.Color = Color3.fromRGB(255, 255, 255)
                s.stroke.Thickness = 2
            else
                s.stroke.Color = getGuideColor(Enum.StudioStyleGuideColor.Border)
                s.stroke.Thickness = 1
            end
        end
    end

    for _, p in presetColors do
        local swatch = Instance.new("TextButton")
        swatch.Name = p.name
        swatch.Size = UDim2.new(0, 20, 0, 20)
        swatch.Position = UDim2.new(0, 0, 0.5, -10)
        swatch.BackgroundColor3 = p.color
        swatch.Text = ""
        swatch.AutoButtonColor = false
        swatch.BorderSizePixel = 0
        swatch.Parent = swatchContainer
        local stroke = addStroke(swatch, getGuideColor(Enum.StudioStyleGuideColor.Border), 1)

        table.insert(swatchElements, { btn = swatch, stroke = stroke, color = p.color })

        swatch.MouseButton1Click:Connect(function()
            onSelect(p.color)
            updateVisual(p.color)
        end)
    end

    hexBox.FocusLost:Connect(function()
        local parsed = parseHex(hexBox.Text)
        if parsed then
            onSelect(parsed)
            updateVisual(parsed)
        else
            hexBox.Text = colorToHex(activeColor)
        end
    end)

    updateVisual(current)

    return container
end


-- ===== PreviewBox.lua =====
-- ================================================================
--  Button FX Studio | Preview Box Component
--  Made by KAMIRIM
--  Fixed preview container with live interactive multi-effect tweening.
-- ================================================================

local TweenService = game:GetService("TweenService")
local RunService   = game:GetService("RunService")

local function createPreviewBox(
    parent: Instance,
    posY: number,
    height: number,
    getGuideColor: (Enum.StudioStyleGuideColor, Enum.StudioStyleGuideModifier?) -> Color3
)
    -- Main container (Fixed between Header and Scroll)
    local box = newFrame(parent, "PreviewBox",
        UDim2.new(1, 0, 0, height),
        UDim2.new(0, 0, 0, posY),
        getGuideColor(Enum.StudioStyleGuideColor.MainBackground)
    )

    -- Bottom border line
    newFrame(box, "BottomBorder",
        UDim2.new(1, 0, 0, 1),
        UDim2.new(0, 0, 1, -1),
        getGuideColor(Enum.StudioStyleGuideColor.Border)
    )

    -- Inner Card for preview canvas
    local canvas = newFrame(box, "Canvas",
        UDim2.new(1, -16, 1, -16),
        UDim2.new(0, 8, 0, 8),
        getGuideColor(Enum.StudioStyleGuideColor.Titlebar)
    )
    canvas.ClipsDescendants = true
    addStroke(canvas, getGuideColor(Enum.StudioStyleGuideColor.Border), 1)

    -- Preview Label (Top Left)
    local previewTag = newLabel(canvas, "PREVIEW",
        UDim2.new(0, 100, 0, 16),
        UDim2.new(0, 8, 0, 6),
        getGuideColor(Enum.StudioStyleGuideColor.SubText),
        11, true
    )

    -- Interactive Target Button (Perfect Center Anchor)
    local previewBtn = newBtn(canvas, "PreviewTarget",
        UDim2.new(0, 140, 0, 34),
        UDim2.new(0.5, 0, 0.5, 2),
        getGuideColor(Enum.StudioStyleGuideColor.MainButton),
        "Click Me!",
        Color3.fromRGB(255, 255, 255),
        14
    )
    previewBtn.ZIndex = 3
    previewBtn.AnchorPoint = Vector2.new(0.5, 0.5)
    previewBtn.Font = Enum.Font.GothamBold
    local defaultStroke = addStroke(previewBtn, getGuideColor(Enum.StudioStyleGuideColor.Border), 1)

    -- Procedural Multi-Ray Radial Sunburst (Inside button with UICorner, 100% contained)
    local sunburstContainer = Instance.new("Frame")
    sunburstContainer.Name = "ButtonFX_Sunburst"
    sunburstContainer.Size = UDim2.new(1, 0, 1, 0)
    sunburstContainer.Position = UDim2.new(0, 0, 0, 0)
    sunburstContainer.BackgroundTransparency = 1
    sunburstContainer.BorderSizePixel = 0
    sunburstContainer.ClipsDescendants = true
    sunburstContainer.ZIndex = previewBtn.ZIndex + 1
    sunburstContainer.Visible = false

    local sunburstCorner = Instance.new("UICorner")
    sunburstCorner.CornerRadius = UDim.new(0, 0)
    sunburstCorner.Parent = sunburstContainer

    local rayRotator = Instance.new("Frame")
    rayRotator.Name = "RayRotator"
    rayRotator.AnchorPoint = Vector2.new(0.5, 0.5)
    rayRotator.Position = UDim2.new(0.5, 0, 0.5, 0)
    rayRotator.Size = UDim2.new(1, 0, 1, 0)
    rayRotator.BackgroundTransparency = 1
    rayRotator.BorderSizePixel = 0
    rayRotator.Parent = sunburstContainer
    sunburstContainer.Parent = previewBtn

    local isHovered = false
    local isPressed = false
    local sunburstRot = 0
    local sunburstSpeed = 45
    local isSunburstActive = false

    local sunburstLayers: { Frame } = {}
    local lastSunburstParams = {
        rayChoice = "",
        spreadAngle = -1,
        rayWidth = -1,
        color = Color3.new(0, 0, 0),
        transparency = -1,
    }

    local function updateMangaSunburst(rayChoice: string, spreadAngle: number, rayWidth: number?, color: Color3, transparency: number, force: boolean?)
        local sliceW = math.clamp(rayWidth or 8, 2, 24)
        local spread = math.clamp(spreadAngle or 18, 2, 80)
        local trans = math.clamp(transparency or 0.35, 0.0, 0.95)

        -- Avoid destroying & recreating frames if parameters haven't changed (eliminates flickering)
        if not force
            and lastSunburstParams.rayChoice == rayChoice
            and lastSunburstParams.spreadAngle == spread
            and lastSunburstParams.rayWidth == sliceW
            and lastSunburstParams.color == color
            and lastSunburstParams.transparency == trans
            and #sunburstLayers > 0
        then
            sunburstContainer.Visible = true
            isSunburstActive = true
            return
        end

        lastSunburstParams.rayChoice = rayChoice
        lastSunburstParams.spreadAngle = spread
        lastSunburstParams.rayWidth = sliceW
        lastSunburstParams.color = color
        lastSunburstParams.transparency = trans

        for _, f in sunburstLayers do
            f:Destroy()
        end
        table.clear(sunburstLayers)

        local btnCorner = previewBtn:FindFirstChildOfClass("UICorner")
        if btnCorner then
            sunburstCorner.CornerRadius = btnCorner.CornerRadius
        end

        local numRays = 8
        if rayChoice == "4-Ray" then
            numRays = 4
        elseif rayChoice == "6-Ray" then
            numRays = 6
        elseif rayChoice == "12-Ray" then
            numRays = 12
        end

        local maxSpread = (360 / (numRays * 2)) - 1
        local clampedSpread = math.clamp(spread, 2, maxSpread * 2)
        local halfSpread = clampedSpread * 0.5
        local step = 0.5

        local btnSize = previewBtn.AbsoluteSize
        local rayRadius = math.max(btnSize.X, btnSize.Y, 150) * 1.6
        local halfRadius = rayRadius * 0.5

        for i = 1, numRays do
            local centerAngle = (i - 1) * (360 / numRays)
            local a = -halfSpread
            while a <= halfSpread + 0.001 do
                local currentAngle = centerAngle + a
                local rad = math.rad(currentAngle)
                local ox = math.sin(rad) * halfRadius
                local oy = -math.cos(rad) * halfRadius

                local slice = Instance.new("Frame")
                slice.Name = "MangaSlice"
                slice.AnchorPoint = Vector2.new(0.5, 0.5)
                slice.Position = UDim2.new(0.5, ox, 0.5, oy)
                slice.Size = UDim2.new(0, sliceW, 0, rayRadius)
                slice.Rotation = currentAngle
                slice.BackgroundColor3 = color
                slice.BackgroundTransparency = trans
                slice.BorderSizePixel = 0
                slice.ZIndex = sunburstContainer.ZIndex
                slice.Parent = rayRotator
                table.insert(sunburstLayers, slice)

                a = a + step
            end
        end

        sunburstContainer.Visible = true
        isSunburstActive = true
    end

    -- Add UIScale for smooth center scaling
    local uiScale = Instance.new("UIScale")
    uiScale.Scale = 1
    uiScale.Parent = previewBtn

    -- Store original base states
    local basePos = previewBtn.Position
    local baseBgColor = previewBtn.BackgroundColor3
    local baseStrokeColor = defaultStroke.Color
    local baseStrokeThickness = defaultStroke.Thickness

    -- Continuous 60+ FPS butter-smooth rotation loop
    RunService.Heartbeat:Connect(function(dt)
        if isSunburstActive and sunburstContainer.Visible and sunburstContainer:IsDescendantOf(game) then
            if sunburstSpeed > 0 then
                sunburstRot = (sunburstRot + dt * sunburstSpeed) % 360
                rayRotator.Rotation = sunburstRot
            end
        end
    end)

    -- Helper to find enabled effects in a category
    local function getActiveEffects(categoryKey: string): { EffectDef }
        local active = {}
        for _, cat in CATALOG do
            if cat.key == categoryKey then
                for _, eff in cat.effects do
                    if eff.enabled then
                        table.insert(active, eff)
                    end
                end
            end
        end
        return active
    end

    -- Dedicated container for ClickRipple (guarantees Sunburst Aura is never clipped)
    local rippleContainer = Instance.new("Frame")
    rippleContainer.Name = "ButtonFX_RippleContainer"
    rippleContainer.Size = UDim2.new(1, 0, 1, 0)
    rippleContainer.Position = UDim2.new(0, 0, 0, 0)
    rippleContainer.BackgroundTransparency = 1
    rippleContainer.BorderSizePixel = 0
    rippleContainer.ClipsDescendants = true
    rippleContainer.ZIndex = previewBtn.ZIndex + 1

    local btnCorner = previewBtn:FindFirstChildOfClass("UICorner")
    if btnCorner then
        local rcCorner = Instance.new("UICorner")
        rcCorner.CornerRadius = btnCorner.CornerRadius
        rcCorner.Parent = rippleContainer
    end
    rippleContainer.Parent = previewBtn

    -- Ripple effect helper
    local function spawnRipple(color: Color3, duration: number)
        local ripple = Instance.new("Frame")
        ripple.Name = "Ripple"
        ripple.AnchorPoint = Vector2.new(0.5, 0.5)
        ripple.Position = UDim2.new(0.5, 0, 0.5, 0)
        ripple.Size = UDim2.new(0, 0, 0, 0)
        ripple.BackgroundColor3 = color
        ripple.BackgroundTransparency = 0.4
        ripple.BorderSizePixel = 0
        ripple.ZIndex = rippleContainer.ZIndex

        local corner = Instance.new("UICorner")
        corner.CornerRadius = UDim.new(1, 0)
        corner.Parent = ripple
        ripple.Parent = rippleContainer

        local maxSize = math.max(previewBtn.AbsoluteSize.X, previewBtn.AbsoluteSize.Y) * 2.2
        local tweenInfo = TweenInfo.new(duration, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
        local t = TweenService:Create(ripple, tweenInfo, {
            Size = UDim2.new(0, maxSize, 0, maxSize),
            BackgroundTransparency = 1,
        })
        t:Play()
        t.Completed:Connect(function()
            ripple:Destroy()
        end)
    end

    -- Visual Particle Effects
    local function spawnSparklePop(color: Color3, count: number, size: number, distance: number, duration: number)
        local n = math.clamp(count or 4, 2, 8)
        local starSize = size or 24
        for i = 1, n do
            local angle = (i / n) * math.pi * 2 + (math.random() * 0.4)
            local dx = math.cos(angle) * distance
            local dy = math.sin(angle) * distance

            local sp = Instance.new("ImageLabel")
            sp.Name = "SparklePop"
            sp.Image = ASSET_DATA.Sparkle4Point
            sp.ImageColor3 = color
            sp.BackgroundTransparency = 1
            sp.Size = UDim2.new(0, starSize * 0.4, 0, starSize * 0.4)
            sp.AnchorPoint = Vector2.new(0.5, 0.5)
            sp.Position = UDim2.new(0.5, 0, 0.5, 0)
            sp.ZIndex = previewBtn.ZIndex + 2
            sp.Parent = previewBtn

            local t = TweenService:Create(sp, TweenInfo.new(duration, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
                Position = UDim2.new(0.5, dx, 0.5, dy),
                Size = UDim2.new(0, starSize, 0, starSize),
                Rotation = math.random(-90, 90),
                ImageTransparency = 1,
            })
            t:Play()
            t.Completed:Connect(function() sp:Destroy() end)
        end
    end

    local function spawnHalftoneWave(color: Color3, scale: number, duration: number)
        local ht = Instance.new("ImageLabel")
        ht.Name = "HalftoneWave"
        ht.Image = ASSET_DATA.HalftoneRadial
        ht.ImageColor3 = color
        ht.BackgroundTransparency = 1
        ht.Size = UDim2.new(0, 0, 0, 0)
        ht.AnchorPoint = Vector2.new(0.5, 0.5)
        ht.Position = UDim2.new(0.5, 0, 0.5, 0)
        ht.ZIndex = previewBtn.ZIndex + 1
        ht.Parent = previewBtn

        local maxSize = math.max(previewBtn.AbsoluteSize.X, previewBtn.AbsoluteSize.Y) * scale
        local t = TweenService:Create(ht, TweenInfo.new(duration, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
            Size = UDim2.new(0, maxSize, 0, maxSize),
            ImageTransparency = 1,
            Rotation = 45,
        })
        t:Play()
        t.Completed:Connect(function() ht:Destroy() end)
    end

    -- Persistent Shimmer Overlay (Guarantees zero overflow, 100% inside button, Zero GC)
    local shimmerOverlay = Instance.new("Frame")
    shimmerOverlay.Name = "ButtonFX_Shimmer"
    shimmerOverlay.Size = UDim2.new(1, 0, 1, 0)
    shimmerOverlay.Position = UDim2.new(0, 0, 0, 0)
    shimmerOverlay.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
    shimmerOverlay.BackgroundTransparency = 0
    shimmerOverlay.BorderSizePixel = 0
    shimmerOverlay.ZIndex = previewBtn.ZIndex + 1
    shimmerOverlay.Visible = false
    shimmerOverlay.Active = false

    local shimmerCorner = Instance.new("UICorner")
    shimmerCorner.CornerRadius = UDim.new(0, 0)
    shimmerCorner.Parent = shimmerOverlay

    local shimmerGrad = Instance.new("UIGradient")
    shimmerGrad.Transparency = NumberSequence.new({
        NumberSequenceKeypoint.new(0, 1),
        NumberSequenceKeypoint.new(0.4, 1),
        NumberSequenceKeypoint.new(0.5, 0.35),
        NumberSequenceKeypoint.new(0.6, 1),
        NumberSequenceKeypoint.new(1, 1),
    })
    shimmerGrad.Parent = shimmerOverlay
    shimmerOverlay.Parent = previewBtn

    local function playShimmer(color: Color3, duration: number, direction: string?, angle: number?)
        local dir = direction or "Right"
        local rot = angle or 25

        local btnCorner = previewBtn:FindFirstChildOfClass("UICorner")
        if btnCorner then
            shimmerCorner.CornerRadius = btnCorner.CornerRadius
        end

        shimmerOverlay.BackgroundColor3 = color
        shimmerGrad.Rotation = rot

        local startOffset: Vector2
        local endOffset: Vector2

        if dir == "Left" then
            startOffset = Vector2.new(1.3, 0)
            endOffset = Vector2.new(-1.3, 0)
        elseif dir == "Down" then
            startOffset = Vector2.new(0, -1.3)
            endOffset = Vector2.new(0, 1.3)
        elseif dir == "Up" then
            startOffset = Vector2.new(0, 1.3)
            endOffset = Vector2.new(0, -1.3)
        else -- "Right"
            startOffset = Vector2.new(-1.3, 0)
            endOffset = Vector2.new(1.3, 0)
        end

        shimmerGrad.Offset = startOffset
        shimmerOverlay.Visible = true

        local t = TweenService:Create(shimmerGrad, TweenInfo.new(duration, Enum.EasingStyle.Linear, Enum.EasingDirection.InOut), {
            Offset = endOffset,
        })
        t:Play()
        t.Completed:Connect(function()
            if shimmerGrad.Offset == endOffset then
                shimmerOverlay.Visible = false
            end
        end)
    end

    local idleTweens: { [string]: Tween } = {}
    local applyDefaultState: () -> ()
    local applyHoverState: () -> ()
    local startIdleTweens: () -> ()

    -- Stop active Idle loops (only cancels physical transform tweens, preserves Sunburst)
    local function stopIdleTweens()
        for key, tw in idleTweens do
            tw:Cancel()
        end
        table.clear(idleTweens)
    end

    -- Start active Idle loops (plays non-conflicting idle tweens alongside hover/click)
    startIdleTweens = function()
        stopIdleTweens()
        if isPressed then return end

        local activeIdle = getActiveEffects("Idle")
        local activeHover = getActiveEffects("Hover")
        local hoverDrivesScale = false
        local hoverDrivesPos = false
        local hoverDrivesRot = false
        local hoverDrivesStroke = false

        if isHovered and #activeHover > 0 then
            for _, eff in activeHover do
                if eff.id == "ScaleUp" then hoverDrivesScale = true end
                if eff.id == "Lift" then hoverDrivesPos = true end
                if eff.id == "Tilt" then hoverDrivesRot = true end
                if eff.id == "Glow" then hoverDrivesStroke = true end
            end
        end

        local hasSunburst = false
        for _, eff in activeIdle do
            local spd = eff.params.speed or 1.20
            if eff.id == "IdlePulse" and not hoverDrivesScale then
                local scale = eff.params.scale or 1.05
                local t = TweenService:Create(uiScale, TweenInfo.new(spd * 0.5, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut, -1, true), {
                    Scale = scale,
                })
                t:Play()
                idleTweens["IdlePulse"] = t
            elseif eff.id == "IdleFloat" and not hoverDrivesPos then
                local dist = eff.params.distance or 6
                local t = TweenService:Create(previewBtn, TweenInfo.new(spd * 0.5, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut, -1, true), {
                    Position = UDim2.new(basePos.X.Scale, basePos.X.Offset, basePos.Y.Scale, basePos.Y.Offset - dist),
                })
                t:Play()
                idleTweens["IdleFloat"] = t
            elseif eff.id == "IdleWobble" and not hoverDrivesRot then
                local ang = eff.params.angle or 4
                previewBtn.Rotation = -ang
                local t = TweenService:Create(previewBtn, TweenInfo.new(spd * 0.5, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut, -1, true), {
                    Rotation = ang,
                })
                t:Play()
                idleTweens["IdleWobble"] = t
            elseif eff.id == "IdleGlow" and not hoverDrivesStroke then
                local c = eff.params.color or Color3.fromRGB(255, 215, 0)
                local th = eff.params.thickness or 3
                local t = TweenService:Create(defaultStroke, TweenInfo.new(spd * 0.5, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut, -1, true), {
                    Color = c,
                    Thickness = baseStrokeThickness + th,
                })
                t:Play()
                idleTweens["IdleGlow"] = t
            elseif eff.id == "IdleSunburst" then
                hasSunburst = true
                local rCount = eff.params.rayCount or "8-Ray"
                local spread = eff.params.spreadAngle or 18
                local rWidth = eff.params.rayWidth or 8
                local c = eff.params.color or Color3.fromRGB(255, 215, 0)
                local trans = eff.params.transparency or 0.35
                sunburstSpeed = eff.params.speed or 45

                updateMangaSunburst(rCount, spread, rWidth, c, trans)
            end
        end

        if not hasSunburst then
            sunburstContainer.Visible = false
            isSunburstActive = false
        end
    end

    -- Apply Hover State (Guarantees non-hovered properties restore smoothly)
    applyHoverState = function()
        local activeHover = getActiveEffects("Hover")
        if #activeHover == 0 then
            applyDefaultState()
            return
        end

        stopIdleTweens()
        local speed = 0.15

        local hasScale = false
        local hasLift = false
        local hasGlow = false
        local hasBrighten = false
        local hasTilt = false

        for _, eff in activeHover do
            local s = eff.params.speed or speed
            if eff.id == "ScaleUp" then
                hasScale = true
                local scale = eff.params.scale or 1.08
                local style = if eff.params.bounce then Enum.EasingStyle.Back else Enum.EasingStyle.Quad
                TweenService:Create(uiScale, TweenInfo.new(s, style, Enum.EasingDirection.Out), {
                    Scale = scale,
                }):Play()
            elseif eff.id == "Lift" then
                hasLift = true
                local dir = eff.params.direction or "Up"
                local dist = eff.params.distance or 6
                local offset = Vector2.new(0, 0)
                if dir == "Up" then offset = Vector2.new(0, -dist)
                elseif dir == "Down" then offset = Vector2.new(0, dist)
                elseif dir == "Left" then offset = Vector2.new(-dist, 0)
                elseif dir == "Right" then offset = Vector2.new(dist, 0)
                end
                TweenService:Create(previewBtn, TweenInfo.new(s, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
                    Position = UDim2.new(basePos.X.Scale, basePos.X.Offset + offset.X, basePos.Y.Scale, basePos.Y.Offset + offset.Y),
                }):Play()
            elseif eff.id == "Glow" then
                hasGlow = true
                local color = eff.params.color or Color3.fromRGB(255, 215, 0)
                local thick = eff.params.thickness or 2
                TweenService:Create(defaultStroke, TweenInfo.new(s, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
                    Color = color,
                    Thickness = baseStrokeThickness + thick,
                }):Play()
            elseif eff.id == "Brighten" then
                hasBrighten = true
                local amt = eff.params.amount or 0.20
                local r = math.min(1, baseBgColor.R + amt)
                local g = math.min(1, baseBgColor.G + amt)
                local b = math.min(1, baseBgColor.B + amt)
                TweenService:Create(previewBtn, TweenInfo.new(s, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
                    BackgroundColor3 = Color3.new(r, g, b),
                }):Play()
            elseif eff.id == "Tilt" then
                hasTilt = true
                local ang = eff.params.angle or 5
                TweenService:Create(previewBtn, TweenInfo.new(s, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
                    Rotation = ang,
                }):Play()
            end
        end

        -- Restore any property not driven by Hover FX
        if not hasScale then
            TweenService:Create(uiScale, TweenInfo.new(speed, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
                Scale = 1,
            }):Play()
        end
        if not hasLift then
            TweenService:Create(previewBtn, TweenInfo.new(speed, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
                Position = basePos,
            }):Play()
        end
        if not hasTilt then
            TweenService:Create(previewBtn, TweenInfo.new(speed, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
                Rotation = 0,
            }):Play()
        end
        if not hasGlow then
            TweenService:Create(defaultStroke, TweenInfo.new(speed, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
                Color = baseStrokeColor,
                Thickness = baseStrokeThickness,
            }):Play()
        end
        if not hasBrighten then
            TweenService:Create(previewBtn, TweenInfo.new(speed, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
                BackgroundColor3 = baseBgColor,
            }):Play()
        end

        startIdleTweens()
    end

    -- Apply Default / Base State (Resumes Idle animations)
    applyDefaultState = function()
        local speed = 0.15
        stopIdleTweens()

        local activeIdle = getActiveEffects("Idle")
        local hasIdlePulse = false
        local hasIdleFloat = false
        local hasIdleWobble = false
        local hasIdleGlow = false

        for _, eff in activeIdle do
            if eff.id == "IdlePulse" then hasIdlePulse = true end
            if eff.id == "IdleFloat" then hasIdleFloat = true end
            if eff.id == "IdleWobble" then hasIdleWobble = true end
            if eff.id == "IdleGlow" then hasIdleGlow = true end
        end

        if not hasIdlePulse then
            TweenService:Create(uiScale, TweenInfo.new(speed, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
                Scale = 1,
            }):Play()
        end
        if not hasIdleFloat then
            TweenService:Create(previewBtn, TweenInfo.new(speed, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
                Position = basePos,
            }):Play()
        end
        if not hasIdleWobble then
            TweenService:Create(previewBtn, TweenInfo.new(speed, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
                Rotation = 0,
            }):Play()
        end
        if not hasIdleGlow then
            TweenService:Create(defaultStroke, TweenInfo.new(speed, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
                Color = baseStrokeColor,
                Thickness = baseStrokeThickness,
            }):Play()
        end
        TweenService:Create(previewBtn, TweenInfo.new(speed, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
            BackgroundColor3 = baseBgColor,
        }):Play()

        startIdleTweens()
    end

    -- Mouse Hover Events
    previewBtn.MouseEnter:Connect(function()
        isHovered = true
        if not isPressed then
            applyHoverState()
        end
    end)

    previewBtn.MouseLeave:Connect(function()
        isHovered = false
        isPressed = false
        applyDefaultState()
    end)

    -- Mouse Click Down (Press)
    previewBtn.MouseButton1Down:Connect(function()
        isPressed = true
        stopIdleTweens()
        local activeClick = getActiveEffects("Click")
        if #activeClick == 0 then return end

        for _, eff in activeClick do
            local speed = eff.params.speed or 0.08
            if eff.id == "ClickSquish" then
                local scale = eff.params.scale or 0.90
                local style = if eff.params.bounce then Enum.EasingStyle.Back else Enum.EasingStyle.Quad
                TweenService:Create(uiScale, TweenInfo.new(speed, style, Enum.EasingDirection.Out), {
                    Scale = scale,
                }):Play()
            elseif eff.id == "ClickPunch" then
                local dir = eff.params.direction or "Down"
                local dist = eff.params.distance or 4
                local offset = Vector2.new(0, 0)
                if dir == "Up" then offset = Vector2.new(0, -dist)
                elseif dir == "Down" then offset = Vector2.new(0, dist)
                elseif dir == "Left" then offset = Vector2.new(-dist, 0)
                elseif dir == "Right" then offset = Vector2.new(dist, 0)
                end
                TweenService:Create(previewBtn, TweenInfo.new(speed, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
                    Position = UDim2.new(basePos.X.Scale, basePos.X.Offset + offset.X, basePos.Y.Scale, basePos.Y.Offset + offset.Y),
                }):Play()
            elseif eff.id == "ClickShake" then
                local ang = eff.params.angle or 5
                local t1 = TweenService:Create(previewBtn, TweenInfo.new(speed * 0.5, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
                    Rotation = ang,
                })
                t1:Play()
                t1.Completed:Connect(function()
                    if isPressed then
                        TweenService:Create(previewBtn, TweenInfo.new(speed * 0.5, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
                            Rotation = -ang,
                        }):Play()
                    end
                end)
            elseif eff.id == "ClickFlash" then
                local color = eff.params.color or Color3.fromRGB(255, 255, 255)
                local dur = eff.params.duration or 0.12
                TweenService:Create(previewBtn, TweenInfo.new(dur * 0.4, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
                    BackgroundColor3 = color,
                }):Play()
            elseif eff.id == "ClickRipple" then
                local color = eff.params.color or Color3.fromRGB(255, 255, 255)
                local dur = eff.params.duration or 0.35
                spawnRipple(color, dur)
            elseif eff.id == "ClickSparkle" then
                local col = eff.params.color or Color3.fromRGB(255, 215, 0)
                local cnt = eff.params.count or 4
                local sz = eff.params.size or 24
                local dist = eff.params.distance or 40
                local dur = eff.params.duration or 0.40
                spawnSparklePop(col, cnt, sz, dist, dur)
            elseif eff.id == "ClickHalftone" then
                local col = eff.params.color or Color3.fromRGB(255, 255, 255)
                local sc = eff.params.scale or 1.60
                local dur = eff.params.duration or 0.35
                spawnHalftoneWave(col, sc, dur)
            end
        end
    end)

    -- Mouse Click Release Handler
    local function handleRelease()
        if isPressed then
            isPressed = false
            local activeHover = getActiveEffects("Hover")
            if isHovered and #activeHover > 0 then
                applyHoverState()
            else
                applyDefaultState()
            end
        end
    end

    previewBtn.MouseButton1Up:Connect(handleRelease)
    previewBtn.Activated:Connect(handleRelease)
    previewBtn.InputEnded:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
            handleRelease()
        end
    end)

    -- Background Shimmer Loop
    task.spawn(function()
        while true do
            local activeIdle = getActiveEffects("Idle")
            local shimmerEff: EffectDef? = nil
            for _, eff in activeIdle do
                if eff.id == "IdleShimmer" then
                    shimmerEff = eff
                    break
                end
            end

            if shimmerEff and previewBtn:IsDescendantOf(game) then
                local c = shimmerEff.params.color or Color3.fromRGB(255, 255, 255)
                local spd = shimmerEff.params.speed or 0.60
                local intv = shimmerEff.params.interval or 2.50
                local dir = shimmerEff.params.direction or "Right"
                local ang = shimmerEff.params.angle or 25
                playShimmer(c, spd, dir, ang)
                task.wait(intv)
            else
                task.wait(1)
            end
        end
    end)

    -- Instant Preview Triggers for Live Settings Adjustment
    local function triggerHoverPreview()
        if isPressed then return end
        applyHoverState()
        task.delay(0.4, function()
            if not isHovered and not isPressed then
                applyDefaultState()
            end
        end)
    end

    local function triggerClickPreview()
        isPressed = true
        stopIdleTweens()
        local activeClick = getActiveEffects("Click")
        local speed = 0.08

        for _, eff in activeClick do
            local s = eff.params.speed or speed
            if eff.id == "ClickSquish" then
                local scale = eff.params.scale or 0.90
                local style = if eff.params.bounce then Enum.EasingStyle.Back else Enum.EasingStyle.Quad
                TweenService:Create(uiScale, TweenInfo.new(s, style, Enum.EasingDirection.Out), {
                    Scale = scale,
                }):Play()
            elseif eff.id == "ClickPunch" then
                local dir = eff.params.direction or "Down"
                local dist = eff.params.distance or 4
                local offset = Vector2.new(0, 0)
                if dir == "Up" then offset = Vector2.new(0, -dist)
                elseif dir == "Down" then offset = Vector2.new(0, dist)
                elseif dir == "Left" then offset = Vector2.new(-dist, 0)
                elseif dir == "Right" then offset = Vector2.new(dist, 0)
                end
                TweenService:Create(previewBtn, TweenInfo.new(s, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
                    Position = UDim2.new(basePos.X.Scale, basePos.X.Offset + offset.X, basePos.Y.Scale, basePos.Y.Offset + offset.Y),
                }):Play()
            elseif eff.id == "ClickShake" then
                local ang = eff.params.angle or 5
                TweenService:Create(previewBtn, TweenInfo.new(s * 0.5, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
                    Rotation = ang,
                }):Play()
            elseif eff.id == "ClickFlash" then
                local color = eff.params.color or Color3.fromRGB(255, 255, 255)
                local dur = eff.params.duration or 0.12
                TweenService:Create(previewBtn, TweenInfo.new(dur * 0.4, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
                    BackgroundColor3 = color,
                }):Play()
            elseif eff.id == "ClickRipple" then
                local color = eff.params.color or Color3.fromRGB(255, 255, 255)
                local dur = eff.params.duration or 0.35
                spawnRipple(color, dur)
            elseif eff.id == "ClickSparkle" then
                local col = eff.params.color or Color3.fromRGB(255, 215, 0)
                local cnt = eff.params.count or 4
                local sz = eff.params.size or 24
                local dist = eff.params.distance or 40
                local dur = eff.params.duration or 0.40
                spawnSparklePop(col, cnt, sz, dist, dur)
            elseif eff.id == "ClickHalftone" then
                local col = eff.params.color or Color3.fromRGB(255, 255, 255)
                local sc = eff.params.scale or 1.60
                local dur = eff.params.duration or 0.35
                spawnHalftoneWave(col, sc, dur)
            end
        end

        task.delay(0.25, function()
            isPressed = false
            if isHovered then
                applyHoverState()
            else
                applyDefaultState()
            end
        end)
    end

    applyDefaultState()

    return {
        box                 = box,
        canvas              = canvas,
        button              = previewBtn,
        previewTag          = previewTag,
        refreshPreview      = applyDefaultState,
        triggerHoverPreview = triggerHoverPreview,
        triggerClickPreview = triggerClickPreview,
    }
end


-- ===== main.lua =====
-- ================================================================
--  Button FX Studio | Main Entry Point
--  Made by KAMIRIM
--  Builds the widget UI and wires up all logic using native Studio theme.
--  Supports both Standalone Production and Hot-Reload Dev Bridge.
-- ================================================================

local studioTheme = settings().Studio.Theme

local function getGuideColor(guideColor: Enum.StudioStyleGuideColor, modifier: Enum.StudioStyleGuideModifier?): Color3
    if modifier then
        return studioTheme:GetColor(guideColor, modifier)
    else
        return studioTheme:GetColor(guideColor)
    end
end

local HEADER_H  = 54
local PREVIEW_H = 100
local BOTTOM_H  = 84

local selectionConn: RBXScriptConnection? = nil

local function mountUI(widget: DockWidgetPluginGui, plug: Plugin)
    -- Clean up previous UI and connections
    if selectionConn then
        selectionConn:Disconnect()
        selectionConn = nil
    end
    for _, child in widget:GetChildren() do
        child:Destroy()
    end

    -- ── Root ──────────────────────────────────────────────────────────
    local root = newFrame(widget, "Root",
        UDim2.new(1,0,1,0), UDim2.new(0,0,0,0),
        getGuideColor(Enum.StudioStyleGuideColor.MainBackground))

    -- ── Header ────────────────────────────────────────────────────────
    local hdr = newFrame(root, "Header",
        UDim2.new(1,0,0,HEADER_H), UDim2.new(0,0,0,0),
        getGuideColor(Enum.StudioStyleGuideColor.Titlebar))

    -- Bottom border line
    newFrame(hdr, "Border",
        UDim2.new(1,0,0,1), UDim2.new(0,0,1,-1),
        getGuideColor(Enum.StudioStyleGuideColor.Border))

    -- Title
    newLabel(hdr, "Button FX Studio",
        UDim2.new(1, -48, 0, 24), UDim2.new(0,10,0,5),
        getGuideColor(Enum.StudioStyleGuideColor.MainText), 15, true)

    -- Help button [?]
    local helpBtn = newBtn(hdr, "HelpBtn",
        UDim2.new(0, 24, 0, 24), UDim2.new(1, -34, 0, 15),
        getGuideColor(Enum.StudioStyleGuideColor.Button),
        "?",
        getGuideColor(Enum.StudioStyleGuideColor.ButtonText),
        13)
    helpBtn.Font = Enum.Font.GothamBold
    addStroke(helpBtn, getGuideColor(Enum.StudioStyleGuideColor.Border), 1)

    helpBtn.MouseButton1Click:Connect(function()
        local ok = pcall(function()
            plug:OpenBrowserWindow(PLUGIN_URLS.Website)
        end)
        if not ok then
            pcall(function()
                game:GetService("GuiService"):OpenBrowserWindow(PLUGIN_URLS.Website)
            end)
        end
    end)

    -- Status bar
    local statusLbl = newLabel(hdr, "Pick a button in Explorer.",
        UDim2.new(1, -48, 0, 18), UDim2.new(0,10,0,29),
        getGuideColor(Enum.StudioStyleGuideColor.SubText), 12, false)

    -- Status Helper
    local function setStatus(text: string, isError: boolean?, isSuccess: boolean?)
        statusLbl.Text = text
        if isError then
            statusLbl.TextColor3 = Color3.fromRGB(255, 80, 80)
        elseif isSuccess then
            statusLbl.TextColor3 = Color3.fromRGB(80, 220, 120)
        else
            statusLbl.TextColor3 = getGuideColor(Enum.StudioStyleGuideColor.SubText)
        end
    end

    -- ── Fixed Preview Box ─────────────────────────────────────────────
    local preview = createPreviewBox(root, HEADER_H, PREVIEW_H, getGuideColor)

    -- ── Scroll Area ───────────────────────────────────────────────────
    local scroll = Instance.new("ScrollingFrame")
    scroll.Name                 = "Scroll"
    scroll.Size                 = UDim2.new(1, 0, 1, -(HEADER_H + PREVIEW_H + BOTTOM_H))
    scroll.Position             = UDim2.new(0, 0, 0, HEADER_H + PREVIEW_H)
    scroll.BackgroundColor3     = getGuideColor(Enum.StudioStyleGuideColor.MainBackground)
    scroll.BorderSizePixel      = 0
    scroll.ScrollBarThickness   = 5
    scroll.ScrollBarImageColor3 = getGuideColor(Enum.StudioStyleGuideColor.ScrollBar)
    scroll.AutomaticCanvasSize  = Enum.AutomaticSize.Y
    scroll.CanvasSize           = UDim2.new(1, 0, 0, 0)
    scroll.Parent               = root

    local content = newFrame(scroll, "Content",
        UDim2.new(1,0,0,0), UDim2.new(0,0,0,0),
        getGuideColor(Enum.StudioStyleGuideColor.MainBackground))
    content.AutomaticSize = Enum.AutomaticSize.Y
    addVList(content, 0)
    addPadding(content, 8, 0, 8, 0)

    -- ── Effect Sections ───────────────────────────────────────────────
    for si, cat in CATALOG do
        -- Section wrapper
        local sec = newFrame(content, cat.key .. "Sec",
            UDim2.new(1,0,0,0), UDim2.new(0,0,0,0), nil)
        sec.LayoutOrder   = (si - 1) * 2 + 1
        sec.AutomaticSize = Enum.AutomaticSize.Y
        addVList(sec, 4)
        addPadding(sec, 10, 10, 8, 10)

        -- Section title label
        local titleLbl = newLabel(sec, cat.label,
            UDim2.new(1,0,0,22), UDim2.new(0,0,0,0),
            getGuideColor(Enum.StudioStyleGuideColor.SubText), 12, true)
        titleLbl.LayoutOrder = 1

        -- If category has no effects defined yet
        if #cat.effects == 0 then
            local emptyLbl = newLabel(sec, "(Coming soon in next update)",
                UDim2.new(1,0,0,24), UDim2.new(0,8,0,0),
                getGuideColor(Enum.StudioStyleGuideColor.SubText), 11, false)
            emptyLbl.LayoutOrder = 2
        end

        -- Build effect rows with Checkboxes & Drawers
        local updateAllCheckboxes: () -> ()

        local checkboxCallbacks = {}

        for idx, eff in cat.effects do
            local card = newFrame(sec, "Card_" .. eff.id,
                UDim2.new(1, 0, 0, 0), UDim2.new(0, 0, 0, 0),
                getGuideColor(Enum.StudioStyleGuideColor.Titlebar)
            )
            card.LayoutOrder = 1 + idx
            card.AutomaticSize = Enum.AutomaticSize.Y
            addStroke(card, getGuideColor(Enum.StudioStyleGuideColor.Border), 1)
            addVList(card, 0)

            -- Main row
            local row = newFrame(card, "Row",
                UDim2.new(1, 0, 0, 32), UDim2.new(0, 0, 0, 0),
                nil
            )

            -- Effect name label (Clickable full-row button to toggle)
            local nameBtn = newBtn(row, "NameBtn",
                UDim2.new(1, -38, 1, 0), UDim2.new(0, 10, 0, 0),
                Color3.new(0,0,0),
                eff.name,
                getGuideColor(Enum.StudioStyleGuideColor.MainText),
                13
            )
            nameBtn.BackgroundTransparency = 1
            nameBtn.TextXAlignment = Enum.TextXAlignment.Left

            -- Settings toggle button (Gear icon)
            local gearBtn = newBtn(row, "GearBtn",
                UDim2.new(0, 24, 0, 24), UDim2.new(1, -28, 0.5, -12),
                getGuideColor(Enum.StudioStyleGuideColor.Button),
                "⚙",
                getGuideColor(Enum.StudioStyleGuideColor.ButtonText),
                12
            )
            gearBtn.Font = Enum.Font.GothamBold
            addStroke(gearBtn, getGuideColor(Enum.StudioStyleGuideColor.Border), 1)

            -- Settings Drawer (Collapsible)
            local drawer = newFrame(card, "Drawer",
                UDim2.new(1, 0, 0, 0), UDim2.new(0, 0, 0, 0),
                getGuideColor(Enum.StudioStyleGuideColor.MainBackground)
            )
            drawer.AutomaticSize = Enum.AutomaticSize.Y
            drawer.Visible = false
            addVList(drawer, 3)
            addPadding(drawer, 6, 8, 6, 8)
            newFrame(drawer, "Sep", UDim2.new(1, 0, 0, 1), UDim2.new(0, 0, 0, 0), getGuideColor(Enum.StudioStyleGuideColor.Border))

            -- Live preview feedback helper
            local function onParamChange()
                if cat.key == "Hover" then
                    if preview and preview.triggerHoverPreview then
                        preview.triggerHoverPreview()
                    end
                elseif cat.key == "Click" then
                    if preview and preview.triggerClickPreview then
                        preview.triggerClickPreview()
                    end
                elseif cat.key == "Idle" then
                    if preview and preview.refreshPreview then
                        preview.refreshPreview()
                    end
                end
            end

            -- Populate Drawer inputs based on effect ID
            if eff.id == "ScaleUp" then
                createNumberInput(drawer, "Scale Multiplier", eff.params.scale or 1.08, 1.01, 2.00, function(n)
                    eff.params.scale = n
                    onParamChange()
                end, getGuideColor)
                createNumberInput(drawer, "Speed (Seconds)", eff.params.speed or 0.15, 0.01, 2.00, function(n)
                    eff.params.speed = n
                    onParamChange()
                end, getGuideColor)
            elseif eff.id == "Lift" then
                createChoiceInput(drawer, "Direction", {"Up", "Down", "Left", "Right"}, eff.params.direction or "Up", function(d)
                    eff.params.direction = d
                    onParamChange()
