                                        else getGuideColor(Enum.StudioStyleGuideColor.Titlebar)
            end
            table.insert(checkboxCallbacks, refreshVisual)

            -- Click handler
            local function onToggle()
                toggleEffect(cat.key, eff.id, not eff.enabled)
                for _, cb in checkboxCallbacks do
                    cb()
                end
                if preview and preview.refreshPreview then
                    preview.refreshPreview()
                end
            end
            nameBtn.MouseButton1Click:Connect(onToggle)
