    local applyBtn = newBtn(bottom, "ApplyBtn",
        UDim2.new(0.55,-14,0,32), UDim2.new(0,10,0,8),
        getGuideColor(Enum.StudioStyleGuideColor.MainButton),
        "Apply FX",
        Color3.fromRGB(255, 255, 255),
        14)
    applyBtn.Font = Enum.Font.GothamBold
    addStroke(applyBtn, getGuideColor(Enum.StudioStyleGuideColor.Border), 1)

    -- Remove button (right)
    local removeBtn = newBtn(bottom, "RemoveBtn",
        UDim2.new(0.45,-14,0,32), UDim2.new(0.55,4,0,8),
        getGuideColor(Enum.StudioStyleGuideColor.Button),
        "Remove FX",
        getGuideColor(Enum.StudioStyleGuideColor.ButtonText),
        14)
    removeBtn.Font = Enum.Font.GothamBold
    addStroke(removeBtn, getGuideColor(Enum.StudioStyleGuideColor.Border), 1)

    -- Footer Strip (Author + Donate)
