        UDim2.new(1, -20, 0, 24), UDim2.new(0, 10, 0, 48),
        nil)

    local footerLbl = newLabel(footerStrip, "Made by KAMIRIM",
        UDim2.new(0.5, -4, 1, 0), UDim2.new(0, 0, 0, 0),
        getGuideColor(Enum.StudioStyleGuideColor.SubText), 11, false)

    local donateBtn = newBtn(footerStrip, "DonateBtn",
        UDim2.new(0.5, 0, 1, 0), UDim2.new(0.5, 0, 0, 0),
        getGuideColor(Enum.StudioStyleGuideColor.Button),
        "☕ Donate",
        Color3.fromRGB(255, 195, 60),
        11)
    donateBtn.Font = Enum.Font.GothamBold
    addStroke(donateBtn, getGuideColor(Enum.StudioStyleGuideColor.Border), 1)

    donateBtn.MouseButton1Click:Connect(function()
        local ok = pcall(function()
            plug:OpenBrowserWindow(PLUGIN_URLS.Donate)
        end)
        if not ok then
            pcall(function()
                game:GetService("GuiService"):OpenBrowserWindow(PLUGIN_URLS.Donate)
            end)
        end
    end)

    -- Apply Logic
    applyBtn.MouseButton1Click:Connect(function()
        local btns = getButtons()
        if #btns == 0 then
            setStatus("No button selected!", true, false)
            return
        end
        History:SetWaypoint("ButtonFX Apply")
        for _, b in btns do
            applyFX(b)
        end
        History:SetWaypoint("ButtonFX Apply Done")
        setStatus(string.format("Done! Applied to %d button(s).", #btns), false, true)
    end)

    -- Remove Logic
    removeBtn.MouseButton1Click:Connect(function()
        local btns = getButtons()
        if #btns == 0 then
            setStatus("No button selected!", true, false)
            return
        end
        History:SetWaypoint("ButtonFX Remove")
        local n = 0
        for _, b in btns do
            if removeFX(b) then n += 1 end
        end
        History:SetWaypoint("ButtonFX Remove Done")
        if n > 0 then
            setStatus(string.format("Removed from %d button(s).", n), false, true)
        else
            setStatus("No ButtonFX script found.", false, false)
        end
    end)

    -- Selection Listener
    local function updateSelectionStatus()
        local btns = getButtons()
        if #btns == 0 then
            setStatus("Pick a button in Explorer.", false, false)
        elseif #btns == 1 then
            setStatus("Ready — 1 button selected.", false, true)
        else
            setStatus(string.format("Ready — %d buttons selected.", #btns), false, true)
        end
    end
    selectionConn = Selection.SelectionChanged:Connect(updateSelectionStatus)
    updateSelectionStatus()
end

-- ── Widget ────────────────────────────────────────────────────────
local widgetInfo = DockWidgetPluginGuiInfo.new(
    Enum.InitialDockState.Right,
    false, false,  -- enabled, overrideEnabled
    280, 560,      -- default width, height
    220, 420       -- min width, height
)
local widget = plugin:CreateDockWidgetPluginGui("ButtonFXStudio_v2", widgetInfo)
widget.Title         = "Button FX Studio"
widget.ZIndexBehavior = Enum.ZIndexBehavior.Sibling

-- ── Toolbar ───────────────────────────────────────────────────────
local toolbar   = plugin:CreateToolbar("Button FX")
local toggleBtn = toolbar:CreateButton(
    "Button FX Studio",
    "Open / Close Button FX Studio",
    ""
)
toggleBtn.ClickableWhenViewportHidden = true

toggleBtn.Click:Connect(function()
    widget.Enabled = not widget.Enabled
end)
widget:BindToClose(function()
    widget.Enabled = false
end)

-- ── Mount ──────────────────────────────────────────────────────────
mountUI(widget, plugin)

